<?php

declare(strict_types=1);
if (basename((string)($_SERVER['SCRIPT_FILENAME'] ?? '')) === basename(__FILE__)) { http_response_code(403); exit; }

function skill_percent_bar(float $value): string { return '<i class="skill-bar"><em style="width:'.max(0,min(100,$value)).'%"></em></i>'; }
function skill_state_label(string $state): string { return match($state){'locked'=>tr('Zamčeno'),'available'=>tr('Dostupné'),'in_progress'=>tr('Rozpracováno'),'mastery_ready'=>'Mastery ready','mastered'=>'Mastered',default=>$state}; }
function skill_tier_label(int $tier): string { return [1=>'Foundations',2=>'Core',3=>'Applied',4=>'Advanced',5=>'Mastery'][$tier]??tr('Skill'); }

function render_skill_overview(string $classId,array $module,string $flash=''): void
{
    skill_sync_existing_learning($classId); $branches=skill_branch_progress_map($classId); $defs=skill_branches(); $curr=skill_curriculum($classId); $next=skill_next_recommendation($classId); $overall=skill_overall_mastery($classId); $spec=skill_specialization_for($classId); $assignments=skill_student_assignments($classId);
    render_header(tr('Skill Trees'),$module); ?>
    <?php if($flash!==''):?><div class="notice"><?=e($flash)?></div><?php endif;?>
    <section class="hero skill-hero"><div class="eyebrow"><?=e(tr('Dovednosti'))?></div><h1><?=e(tr('Co je další?'))?></h1><p><?=e(tr('Nejdřív řeš doporučenou dovednost. Celou mapu a mastery statistiky otevři jen tehdy, když je potřebuješ.'))?></p></section>
    <?php if($next):$s=$next['skill'];$p=$next['progress'];?><section class="skill-next-card"><div><span><?=e(tr('DOPORUČENÝ DALŠÍ KROK'))?></span><h2><?=edu_cs((string)$s['name'])?></h2><p><?=e((string)$next['reason'])?> · <?=edu_cs((string)$s['description'])?></p></div><div><a class="btn primary" href="<?=e(v69_task_url('skill',['skill'=>(string)$s['slug']], '?view=skills'))?>"><?=e(tr('Pokračovat v One Task →'))?></a></div></section><?php endif;?>
    <?php if($assignments):?><section class="dashboard-panel student-skill-assignments"><div class="dashboard-panel-head"><div><div class="eyebrow"><?=e(tr('Zadáno učitelem'))?></div><h2><?=e(tr('Aktuální Skill Assignments'))?></h2><p><?=e(tr('Povinná zadání mají v doporučeních vyšší prioritu, ale mastery stále získáš pouze skutečnou evidencí.'))?></p></div></div><div class="student-assignment-list"><?php foreach(array_slice($assignments,0,6) as $a):$as=skill_find((string)$a['skill']);if(!$as)continue;$ap=skill_progress($classId,(string)$a['skill']);?><a href="<?=e(module_url('skill_detail',['skill'=>(string)$a['skill']]))?>" class="<?=e((string)$a['assignment_type'])?>"><div><span><?=e($a['assignment_type']==='required'?tr('POVINNÉ'):tr('DOPORUČENÉ'))?><?=!empty($a['due_at'])?e(tr(' · do {date}',['date'=>date('d.m.',strtotime((string)$a['due_at']))])):''?></span><strong><?=edu_cs((string)$as['name'])?></strong></div><b><?=edu_number((float)($ap['mastery_percent']??0),0)?> % →</b></a><?php endforeach;?></div></section><?php endif;?>
    <details class="v506-progressive v506-map-details"><summary><span><strong><?=e(tr('Všechny dovednosti'))?></strong><small><?=e(tr('Mapa, mastery a specializace jsou sekundární přehled.'))?></small></span><b><?=e(tr('Zobrazit detail'))?></b></summary><div class="skill-overview-meta"><div><strong><?=edu_number($overall,0)?> %</strong><span><?=e(tr('celková mastery'))?></span></div><div><strong><?=array_sum(array_map(static fn($b)=>(int)$b['skills_mastered'],$branches))?></strong><span><?=e(tr('zvládnuté skills'))?></span></div><div><strong><?=isset($spec['name'])?edu_cs((string)$spec['name']):e('Explorer')?></strong><span><?=e(!empty($spec['unlocked'])?tr('specializace'):tr('nejbližší směr'))?></span></div></div><section class="skill-branch-grid"><?php foreach((array)($curr['branches']??[]) as $branch=>$weight):$b=$branches[$branch]??[];$def=$defs[$branch]??[];$primary=in_array($branch,(array)($curr['primary']??[]),true);?><article class="skill-branch-card"><div class="skill-branch-icon"><?=e((string)($def['icon']??'◇'))?></div><div class="skill-branch-head"><span><?=e($primary?tr('PRIMARY'):tr('BRANCH'))?></span><h2><?=edu_cs((string)($def['name']??$branch))?></h2><p><?=edu_cs((string)($def['description']??''))?></p></div><div class="skill-branch-progress"><strong><?=edu_number((float)($b['mastery_percent']??0),0)?> %</strong><span><?=e(skill_mastery_level_label((string)($b['mastery_level']??'unexplored')))?></span></div><?=skill_percent_bar((float)($b['mastery_percent']??0))?><div class="skill-branch-meta"><span><?=e(tr('{mastered} / {total} mastered',['mastered'=>(int)($b['skills_mastered']??0),'total'=>(int)($b['skills_total']??0)]))?></span><span><?=e(tr('{count} rozpracováno',['count'=>(int)($b['skills_started']??0)]))?></span></div><a class="btn secondary wide" href="<?=e(module_url('skill_branch',['branch'=>$branch]))?>"><?=e(tr('Otevřít strom →'))?></a></article><?php endforeach;?></section></details>
    <!-- v50.6: mastery explanation remains available in existing detail/evidence views; no separate legend wall. -->
    <?php render_footer();
}

function render_skill_branch(string $classId,array $module,string $branch,string $flash=''): void
{
    $def=skill_branches()[$branch]??null;if(!$def||!in_array($branch,skill_relevant_branches($classId),true)){$_SESSION['flash']=tr('Tato větev není v tvém kurikulu.');redirect_to('?view=skills');}
    skill_sync_existing_learning($classId);$map=skill_progress_map($classId);$bp=skill_branch_progress_map($classId)[$branch]??[];$skills=skill_for_branch($branch);$next=null;foreach($skills as $s){$p=$map[(string)$s['slug']]??[];if(in_array((string)($p['unlock_state']??''),['available','in_progress','mastery_ready'],true)){$next=['skill'=>$s,'progress'=>$p];break;}}
    render_header(tr('{name} Skill Tree',['name'=>(string)$def['name']]),$module,true);?>
    <?php if($flash!==''):?><div class="notice"><?=e($flash)?></div><?php endif;?>
    <section class="skill-branch-hero"><a class="text-link" href="?view=skills"><?=e(tr('← Skill Trees'))?></a><div class="skill-branch-icon xl"><?=e((string)$def['icon'])?></div><div><div class="eyebrow">Branch mastery</div><h1><?=e((string)$def['name'])?></h1><p><?=e((string)$def['description'])?></p></div><aside><strong><?=edu_number((float)($bp['mastery_percent']??0),0)?> %</strong><span><?=e(skill_mastery_level_label((string)($bp['mastery_level']??'unexplored')))?></span></aside></section>
    <?php if($next):?><section class="skill-inline-next"><div><span><?=e(tr('NEXT STEP'))?></span><strong><?=e((string)$next['skill']['name'])?></strong><small><?=edu_number((float)$next['progress']['mastery_percent'],0)?> % mastery</small></div><a class="btn primary" href="<?=e(v69_task_url('skill',['skill'=>(string)$next['skill']['slug']], module_url('skill_branch',['branch'=>$branch])))?>"><?=e(tr('Pokračovat v One Task'))?></a></section><?php endif;?>
    <details class="v506-progressive v506-map-details"><summary><span><strong><?=e(tr('Celý strom'))?></strong><small><?=e(tr('Aktuální doporučení je nahoře. Strom použij pro přehled.'))?></small></span><b><?=e(tr('Zobrazit'))?></b></summary><section class="skill-roadmap"><?php foreach([1,2,3,4,5] as $tier):$tierRows=array_values(array_filter($skills,static fn($s)=>(int)$s['tier']===$tier));if(!$tierRows)continue;?><div class="skill-tier"><header><span><?=e(tr('TIER {tier}',['tier'=>$tier]))?></span><h2><?=e(skill_tier_label($tier))?></h2></header><div class="skill-node-grid"><?php foreach($tierRows as $s):$p=$map[(string)$s['slug']]??[];$state=(string)($p['unlock_state']??'locked');?><a class="skill-node state-<?=e($state)?> <?=!empty($s['mastery_node'])?'boss':''?>" href="<?=e(module_url('skill_detail',['skill'=>(string)$s['slug']]))?>"><div class="skill-node-state"><?= $state==='mastered'?'✓':($state==='locked'?'🔒':(!empty($s['mastery_node'])?'★':'◔')) ?></div><div><span><?=e(skill_state_label($state))?></span><strong><?=e((string)$s['name'])?></strong><small><?=e((string)$s['description'])?></small></div><b><?=edu_number((float)($p['mastery_percent']??0),0)?>%</b><?=skill_percent_bar((float)($p['mastery_percent']??0))?></a><?php endforeach;?></div></div><?php endforeach;?></section></details>
    <?php render_footer();
}

function render_skill_detail(string $classId,array $module,string $slug,string $flash=''): void
{
    $skill=skill_find($slug);if(!$skill||!in_array((string)$skill['branch'],skill_relevant_branches($classId),true)){$_SESSION['flash']=tr('Skill nebyl nalezen.');redirect_to('?view=skills');}
    skill_sync_existing_learning($classId);$knowledgeTopic=skill_knowledge_topic($classId,$slug);$p=skill_progress($classId,$slug);$evidence=skill_student_evidence($classId,skill_current_student_key($classId),$slug);usort($evidence,static fn($a,$b)=>strcmp((string)$b['created_at'],(string)$a['created_at']));$branch=skill_branches()[(string)$skill['branch']]??[];$qs=skill_quick_questions($classId,$skill,'practice');$masterQs=skill_quick_questions($classId,$skill,'mastery');$challenge=skill_challenge_for_skill($slug);
    render_header((string)$skill['name'],$module,true);?>
    <?php if($flash!==''):?><div class="notice"><?=e($flash)?></div><?php endif;?>
    <section class="skill-detail-hero"><a class="text-link" href="<?=e(module_url('skill_branch',['branch'=>(string)$skill['branch']]))?>">← <?=e((string)($branch['name']??tr('Skill Tree')))?></a><div class="eyebrow"><?=e(skill_tier_label((int)$skill['tier']))?> · <?=e(skill_state_label((string)$p['unlock_state']))?></div><h1><?=e((string)$skill['name'])?></h1><p><?=e((string)$skill['description'])?></p><div class="skill-detail-score"><strong><?=edu_number((float)$p['mastery_percent'],0)?> %</strong><span><?=e(skill_mastery_level_label((string)$p['mastery_level']))?></span><?=skill_percent_bar((float)$p['mastery_percent'])?></div></section>
    <?php if ((string)$p['unlock_state'] === 'locked'): ?>
    <section class="dashboard-panel skill-lock-panel"><div class="dashboard-panel-head"><div><div class="eyebrow"><?=e(tr('🔒 Ještě zamčeno'))?></div><h2><?=e(tr('Co potřebuješ splnit'))?></h2></div></div><div class="skill-requirements">
    <?php foreach ((array)$p['missing_requirements'] as $m): ?>
      <?php if (($m['type'] ?? '') === 'level'): ?>
        <article><b><?=e(tr('Level {level}',['level'=>(int)$m['need']]))?></b><span><?=e(tr('aktuálně level {level}',['level'=>(int)$m['have']]))?></span></article>
      <?php else: $rs=skill_find((string)$m['skill']); ?>
        <article><b><?=e((string)($rs['name']??$m['skill']))?> ≥ <?=edu_number((float)$m['need'],0)?> %</b><span><?=e(tr('aktuálně {percent} %',['percent'=>edu_number((float)$m['have'],0)]))?></span><a href="<?=e(module_url('skill_detail',['skill'=>(string)$m['skill']]))?>"><?=e(tr('Otevřít →'))?></a></article>
      <?php endif; ?>
    <?php endforeach; ?>
    </div></section>
    <?php render_footer(); return; endif; ?>
    <div class="skill-detail-layout"><section class="dashboard-panel"><div class="dashboard-panel-head"><div><div class="eyebrow">Mastery path</div><h2><?=e(tr('Jak se mastery počítá'))?></h2><p><?=e(tr('Opakované pokusy se nefarmí — pro každý typ se počítá nejlepší validní evidence do svého maxima.'))?></p></div></div><div class="skill-evidence-rules"><?php foreach(skill_evidence_rules($skill) as $type=>$max):$earned=(float)($p['evidence_by_type'][$type]??0);?><article class="<?=$earned>0?'done':''?>"><div><strong><?=e(ucfirst($type))?></strong><span><?=e($earned>0?tr('evidence započítána'):tr('čeká na evidence'))?></span></div><b><?=edu_number($earned,0)?> / <?=edu_number($max,0)?> MP</b><?=skill_percent_bar($max>0?$earned/$max*100:0)?></article><?php endforeach;?></div></section>
    <aside class="dashboard-panel skill-actions"><div class="eyebrow">Next actions</div><h2><?=e(tr('Pokračuj jedním krokem'))?></h2><a class="btn primary wide" href="<?=e(v69_task_url('skill',['skill'=>$slug],module_url('skill_detail',['skill'=>$slug])))?>"><?=e(tr('Spustit One Task Mode →'))?></a><details><summary><?=e(tr('Pokročilé / původní akce'))?></summary><?php if(empty($p['evidence_by_type']['lesson'])):?><?php if($knowledgeTopic):?><div class="skill-kb-action"><p><?=e(tr('Pro tento skill existuje navázaný Knowledge Tour. Po jeho dokončení se Lesson Evidence propíše automaticky.'))?></p><a class="btn primary wide" href="<?=e(module_url('knowledgebase',['topic'=>$knowledgeTopic,'reference'=>1,'kb_class'=>$classId]))?>"><?=e(tr('Otevřít Knowledge Tour →'))?></a></div><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="skill_mark_learning"><input type="hidden" name="skill" value="<?=e($slug)?>"><button class="btn primary wide"><?=e(tr('Dokončit studijní krok · +10 MP'))?></button></form><?php endif;?><?php elseif(empty($p['evidence_by_type']['practice'])||empty($p['evidence_by_type']['quiz'])):?><details open><summary><?=e(tr('Spustit quick check'))?></summary><form method="post" class="skill-check-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="skill_quick_check"><input type="hidden" name="skill" value="<?=e($slug)?>"><input type="hidden" name="mode" value="practice"><?php foreach($qs as $i=>$q):?><fieldset><legend><?=e((string)$q['q'])?></legend><?php foreach((array)$q['options'] as $oi=>$opt):?><label><input type="radio" name="answers[<?=$i?>]" value="<?=$oi?>" required><span><?=e((string)$opt)?></span></label><?php endforeach;?></fieldset><?php endforeach;?><button class="btn primary wide"><?=e(tr('Vyhodnotit check'))?></button></form></details><?php elseif(empty($p['evidence_by_type']['lab'])&&empty($p['evidence_by_type']['project'])):?><form method="post" class="skill-validation-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="skill_request_validation"><input type="hidden" name="skill" value="<?=e($slug)?>"><label><?=e(tr('Co chceš prakticky předvést?'))?><textarea name="note" rows="3" maxlength="800" placeholder="<?=e(tr('Krátce popiš praktickou práci nebo důkaz.'))?>"></textarea></label><button class="btn primary wide"><?=e(tr('Požádat učitele o validaci'))?></button></form><?php elseif((float)$p['mastery_percent']>=70 && empty($p['evidence_by_type']['challenge']) && !$challenge):?><details open><summary><?=e(tr('Mastery check'))?></summary><form method="post" class="skill-check-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="skill_quick_check"><input type="hidden" name="skill" value="<?=e($slug)?>"><input type="hidden" name="mode" value="mastery"><?php foreach($masterQs as $i=>$q):?><fieldset><legend><?=e((string)$q['q'])?></legend><?php foreach((array)$q['options'] as $oi=>$opt):?><label><input type="radio" name="answers[<?=$i?>]" value="<?=$oi?>" required><span><?=e((string)$opt)?></span></label><?php endforeach;?></fieldset><?php endforeach;?><button class="btn primary wide"><?=e(tr('Odevzdat mastery check'))?></button></form></details><?php elseif($challenge):?><a class="btn primary wide" href="<?=e(module_url('mastery_challenge',['challenge'=>(string)$challenge['id']]))?>"><?=e(tr('★ Otevřít Mastery Challenge'))?></a><?php else:?><div class="skill-complete-note"><strong><?=e((string)$p['unlock_state']==='mastered'?tr('✓ Skill Mastered'):tr('Evidence je kompletní'))?></strong><span><?=e(tr('Další kroky najdeš ve stromu.'))?></span></div><?php endif;?></details></aside></div>
    <details class="v506-progressive v506-map-details"><summary><span><strong><?=e(tr('Proč mám {percent} %?',['percent'=>edu_number((float)$p['mastery_percent'],0)]))?></strong><small><?=e(tr('Zobrazit podrobnou evidence historii.'))?></small></span><b><?=e(tr('Evidence'))?></b></summary><section class="dashboard-panel skill-evidence-timeline"><?php if(!$evidence):?><div class="social-empty-mini"><?=e(tr('Zatím žádná evidence.'))?></div><?php else:?><div><?php foreach($evidence as $row):?><article><i class="state-<?=e((string)$row['state'])?>"><?=in_array((string)$row['state'],['automatic','approved'],true)?'✓':((string)$row['state']==='pending'?'…':'×')?></i><div><strong><?=e(ucfirst((string)$row['type']))?></strong><span><?=e((string)$row['source_id'])?> · <?=e(date('d.m.Y H:i',strtotime((string)$row['created_at'])))?></span><?php if(!empty($row['meta']['note'])):?><small><?=e((string)$row['meta']['note'])?></small><?php endif;?></div><b>+<?=edu_number((float)$row['points'],0)?> MP</b></article><?php endforeach;?></div><?php endif;?></section></details>
    <?php render_footer();
}

function render_mastery_challenge(string $classId,array $module,string $challengeId,string $flash=''): void
{
    $c=skill_challenge_find($challengeId);if(!$c){$_SESSION['flash']=tr('Challenge nebyla nalezena.');redirect_to('?view=skills');}$skill=skill_find((string)$c['skill']);$p=skill_progress($classId,(string)$c['skill']);if((string)$p['unlock_state']==='locked'){$_SESSION['flash']=tr('Mastery challenge je zatím zamčená.');redirect_to(module_url('skill_detail',['skill'=>(string)$c['skill']]));}
    render_header((string)$c['title'],$module,true);?>
    <?php if($flash!==''):?><div class="notice"><?=e($flash)?></div><?php endif;?>
    <section class="mastery-brief"><div><div class="eyebrow">★ MASTERY CHALLENGE · <?=e(strtoupper((string)$c['branch']))?></div><h1><?=e((string)$c['title'])?></h1><p><?=e((string)$c['summary'])?></p><div class="mastery-brief-meta"><span><?=e(tr('Pass {percent} %',['percent'=>edu_number((float)$c['pass_score'],0)]))?></span><span><?=e(tr('Hints snižují max. mastery reward'))?></span><span><?=e(tr('Pokusy neodebírají mastery'))?></span></div></div><aside><strong><?=edu_number((float)$p['mastery_percent'],0)?> %</strong><span><?=e(tr('aktuální mastery node'))?></span></aside></section>
    <form method="post" class="mastery-workspace"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="skill_branch_challenge"><input type="hidden" name="challenge" value="<?=e($challengeId)?>"><aside><span><?=e(tr('OBJECTIVES'))?></span><ul><li><?=e(tr('Analyzovat situaci'))?></li><li><?=e(tr('Najít příčinu'))?></li><li><?=e(tr('Zvolit správný postup'))?></li><li><?=e(tr('Ověřit výsledek'))?></li></ul><label><?=e(tr('Využité nápovědy'))?><select name="hints"><option value="0"><?=e(tr('0 · bez nápovědy'))?></option><option value="1"><?=e(tr('1 hint'))?></option><option value="2"><?=e(tr('2 hints'))?></option><option value="3"><?=e(tr('3 hints'))?></option></select></label></aside><section><div class="eyebrow">Scenario check</div><h2><?=e(tr('Rozhoduj podle důkazů, ne podle tipování.'))?></h2><?php foreach((array)$c['questions'] as $i=>$q):?><fieldset><legend><span><?=str_pad((string)($i+1),2,'0',STR_PAD_LEFT)?></span><?=e((string)$q['q'])?></legend><?php foreach((array)$q['options'] as $oi=>$opt):?><label><input type="radio" name="answers[<?=$i?>]" value="<?=$oi?>" required><span><?=e((string)$opt)?></span></label><?php endforeach;?></fieldset><?php endforeach;?><button class="btn primary" type="submit"><?=e(tr('Odevzdat challenge'))?></button></section></form>
    <?php render_footer();
}

function render_mastery_result(string $classId,array $module,string $attemptId): void
{
    $row=null;foreach(skill_attempt_rows() as $a)if(is_array($a)&&(string)($a['id']??'')===$attemptId&&(string)($a['student_key']??'')===skill_current_student_key($classId)){$row=$a;break;}if(!$row){$_SESSION['flash']=tr('Výsledek nebyl nalezen.');redirect_to('?view=skills');}$c=skill_challenge_find((string)$row['challenge']);$skill=skill_find((string)$row['skill']);render_header(tr('Výsledek Mastery Challenge'),$module);?>
    <section class="mastery-result <?=!empty($row['passed'])?'passed':'failed'?>"><div class="eyebrow"><?=e(!empty($row['passed'])?tr('CHALLENGE COMPLETE'):tr('JEŠTĚ NE HOTOVO'))?></div><h1><?=e((string)($c['title']??'Mastery Challenge'))?></h1><div class="mastery-result-score"><strong><?=edu_number((float)$row['score'],0)?> %</strong><span><?=e(!empty($row['passed'])?tr('splněno'):tr('minimum {percent} %',['percent'=>edu_number((float)($c['pass_score']??75),0)]))?></span></div><div class="mastery-result-grid"><article><b><?=edu_number((float)$row['raw_score'],0)?> %</b><span><?=e(tr('raw score'))?></span></article><article><b><?= (int)$row['hints'] ?></b><span><?=e(tr('použité hints'))?></span></article><article><b><?=e(!empty($row['passed'])?tr('+250 XP'):tr('0 XP'))?></b><span><?=e(tr('jednorázová odměna'))?></span></article></div><p><?=e(!empty($row['passed'])?tr('Výsledek se zapsal jako ověřitelná Mastery Evidence. Teď se znovu přepočítaly navazující skilly, branch mastery, achievementy i prestige badge.'):tr('Neúspěšný pokus ti nic nebere. Vrať se k prerequisite skillům, projdi evidence a zkus challenge znovu.'))?></p><div class="hero-actions"><a class="btn primary" href="<?=e(module_url('skill_detail',['skill'=>(string)$row['skill']]))?>"><?=e(tr('Zpět na skill'))?></a><a class="btn secondary" href="<?=e(module_url('skill_branch',['branch'=>(string)($skill['branch']??'')]))?>"><?=e(tr('Celý strom'))?></a></div></section>
    <?php render_footer();
}
